import Foundation
struct DictationMergeResult {
    let text: String
    let selection: NSRange?
}
func mergeDictation(_ transcript: String, into prompt: String, selection: NSRange?) -> DictationMergeResult {
    guard !transcript.isEmpty else {
        return DictationMergeResult(text: prompt, selection: selection)
    }
    let count = prompt.utf16.count
    var effectiveRange = NSRange(location: count, length: 0)
    var stringRange = prompt.endIndex..<prompt.endIndex
    if let candidate = selection,
       candidate.location >= 0,
       candidate.location != NSNotFound,
       candidate.length >= 0,
       candidate.location <= count,
       candidate.length <= count - candidate.location,
       let converted = Range(candidate, in: prompt),
       (converted.lowerBound == prompt.endIndex || prompt.indices.contains(converted.lowerBound)),
       (converted.upperBound == prompt.endIndex || prompt.indices.contains(converted.upperBound)) {
        effectiveRange = candidate
        stringRange = converted
    }
    let prefix = prompt[..<stringRange.lowerBound]
    let suffix = prompt[stringRange.upperBound...]
    func needsSpace(left: Character?, right: Character?) -> Bool {
        guard let left, let right else { return false }
        return !left.isWhitespace && !right.isWhitespace
    }
    let leadingSpace = needsSpace(left: prefix.last, right: transcript.first) ? " " : ""
    let trailingSpace = needsSpace(left: transcript.last, right: suffix.first) ? " " : ""
    let throughTranscript = leadingSpace + transcript
    var result = prompt
    result.replaceSubrange(stringRange, with: throughTranscript + trailingSpace)
    let caret = effectiveRange.location + throughTranscript.utf16.count
    return DictationMergeResult(text: result, selection: NSRange(location: caret, length: 0))
}
